    "row.cup": { en: "Crescent or cup-like object", zh: "新月形或杯状对象", es: "Objeto en media luna o copa", ko: "초승달형 또는 컵형 객체", fr: "Objet en croissant ou en coupe", de: "Sichel- oder becherartiges Objekt", ja: "三日月またはカップ状オブジェクト" },
    "row.cup.i": { en: "Early cup, open shape with concavity", zh: "早期杯状，带凹陷的开口形状", es: "Copa temprana, forma abierta con concavidad", ko: "초기 컵, 오목함이 있는 열린 형태", fr: "Coupe précoce, forme ouverte avec concavité", de: "Früher Becher, offene Form mit Konkavität", ja: "初期カップ、凹みのある開いた形状" },
