    "row.ring": { en: "Thick ring / circular dorsal ruffle", zh: "粗环 / 圆形背侧皱褶", es: "Anillo grueso / ondulación dorsal circular", ko: "두꺼운 고리 / 원형 등쪽 주름", fr: "Anneau épais / repli dorsal circulaire", de: "Dicker Ring / kreisförmige dorsale Kräuselung", ja: "厚いリング / 円形背側ラッフル" },
