    "row.branched": { en: "Branched irregular actin network", zh: "分支状不规则肌动蛋白网络", es: "Red de actina irregular ramificada", ko: "분지형 불규칙 액틴 네트워크", fr: "Réseau d'actine irrégulier ramifié", de: "Verzweigtes unregelmäßiges Aktinnetzwerk", ja: "分岐した不規則なアクチンネットワーク" },
